// Service-account JWT -> access token (once per run), then one call per job.
// Plain Code node because n8n's Google credential can't target the local mock.
const crypto = require('crypto');
const tokenUri = $env.GOOGLE_TOKEN_URI || 'https://oauth2.googleapis.com/token';
const base = ($env.GCAL_BASE_URL || 'https://www.googleapis.com/calendar/v3').replace(/\/+$/, '');
const helpers = this.helpers;
const http = (opts) => helpers.httpRequest({
  json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, ...opts,
});

function serviceAccount() {
  if ($env.GOOGLE_SERVICE_ACCOUNT_JSON_B64) {
    return JSON.parse(Buffer.from($env.GOOGLE_SERVICE_ACCOUNT_JSON_B64, 'base64').toString('utf8'));
  }
  // Local mock only: a throwaway key. Real Google rejects it.
  const { privateKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
  return {
    client_email: 'tori-calendar@mock.iam.gserviceaccount.com',
    private_key: privateKey.export({ type: 'pkcs8', format: 'pem' }),
  };
}

async function accessToken() {
  const sa = serviceAccount();
  const now = Math.floor(Date.now() / 1000);
  const enc = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
  const unsigned = enc({ alg: 'RS256', typ: 'JWT' }) + '.' + enc({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/calendar.events',
    aud: tokenUri,
    iat: now,
    exp: now + 3600,
  });
  const signature = crypto.createSign('RSA-SHA256').update(unsigned).sign(sa.private_key).toString('base64url');
  const res = await http({
    method: 'POST',
    url: tokenUri,
    json: false,
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${unsigned}.${signature}`,
  });
  const body = typeof res.body === 'string' ? JSON.parse(res.body || '{}') : res.body;
  if (res.statusCode !== 200 || !body.access_token) {
    throw new Error(`token endpoint HTTP ${res.statusCode}: ${JSON.stringify(body).slice(0, 300)}`);
  }
  return body.access_token;
}

const errorText = (body) => (body && body.error && (body.error.message || body.error)) || JSON.stringify(body || '').slice(0, 300);

let token;
let tokenError;
try {
  token = await accessToken();
} catch (e) {
  tokenError = e.message;
}

const out = [];
for (const [index, item] of $input.all().entries()) {
  const job = item.json.job;
  const done = (result) => out.push({ json: { job_id: job.job_id, result }, pairedItem: { item: index } });
  if (!token) {
    done({ ok: false, retryable: true, error: `Google auth failed: ${tokenError}` });
    continue;
  }
  const events = `${base}/calendars/${encodeURIComponent(job.calendar_id)}/events`;
  const headers = { Authorization: `Bearer ${token}` };
  try {
    let res;
    let ok;
    if (job.action === 'upsert') {
      res = await http({ method: 'POST', url: events, headers, body: job.event });
      if (res.statusCode === 409) {
        // Event ID already used (retry, update, or deleted earlier): overwrite, which also restores it.
        res = await http({ method: 'PUT', url: `${events}/${encodeURIComponent(job.event_id)}`, headers, body: job.event });
      }
      ok = res.statusCode === 200;
    } else {
      res = await http({ method: 'DELETE', url: `${events}/${encodeURIComponent(job.event_id)}`, headers });
      ok = [200, 204, 404, 410].includes(res.statusCode); // already gone is fine
    }
    const body = res.body && typeof res.body === 'object' ? res.body : {};
    done({
      ok,
      status: res.statusCode,
      body: ok ? { id: body.id, status: body.status, htmlLink: body.htmlLink } : body,
      error: ok ? null : errorText(res.body),
    });
  } catch (e) {
    done({ ok: false, retryable: true, error: e.message });
  }
}
return out;

// text: free-form (works in dev, or inside Meta's 24 h window)
// template: pre-approved template tori_<event> with the same params (production)
const job = $json.job;
const base = String($env.WHATSAPP_BASE_URL || 'https://graph.facebook.com/v21.0').replace(/\/+$/, '');
const oneLine = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, 1000);
const to = String(job.to).replace(/\D/g, '');

const body = ($env.WHATSAPP_MODE || 'text') === 'template'
  ? {
      messaging_product: 'whatsapp',
      to,
      type: 'template',
      template: {
        name: `tori_${job.event}`,
        language: { code: $env.WHATSAPP_TEMPLATE_LANG || 'en' },
        components: [{ type: 'body', parameters: (job.params || []).map((p) => ({ type: 'text', text: oneLine(p) })) }],
      },
    }
  : { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: job.text } };

return { json: { job_id: job.job_id, url: `${base}/${$env.WHATSAPP_PHONE_NUMBER_ID}/messages`, body } };

const req = $('Build WhatsApp message').item.json;
const status = $json.statusCode;
const body = $json.body || {};
if (status === undefined) {
  return { json: { job_id: req.job_id, result: { ok: false, retryable: true, error: `network: ${($json.error && $json.error.message) || 'no response'}` } } };
}
const ok = status >= 200 && status < 300;
return {
  json: {
    job_id: req.job_id,
    result: {
      ok,
      status,
      // 4xx = bad number / template not approved: retrying won't help
      retryable: status === 429 || status >= 500,
      body: ok ? { message_id: body.messages && body.messages[0] && body.messages[0].id } : body,
      error: ok ? null : (body.error && body.error.message) || `HTTP ${status}`,
    },
  },
};
